-- Assessment standards per hub, managed from each hub's Assessment Management page.
CREATE TABLE IF NOT EXISTS hub_assessment_standards (
  id SERIAL PRIMARY KEY,
  hub_key TEXT NOT NULL,
  standard_number TEXT NOT NULL,
  standard_name TEXT NOT NULL,
  subject_set TEXT,
  level TEXT,
  credits INTEGER,
  assessment_type TEXT,
  nzqa_url TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (hub_key, standard_number)
);

ON CONFLICT (hub_key, standard_number) DO NOTHING;
